-- JDL Core Academy Level 1: full client-review curriculum.
-- Paste this entire file into the Supabase SQL Editor for the TEST project.
-- It creates missing Academy tables, updates this course in place, and leaves
-- learner progress, quiz attempts, enrolments and certificates intact.
-- Exercise tanks, vessels, table outputs and correction factors are fictional.
begin;

create table if not exists academy_learners (
  id serial primary key,
  name text not null,
  email text not null unique,
  company text,
  role text not null default 'Learner',
  password_hash text not null,
  status text not null default 'active',
  last_login_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists academy_courses (
  id serial primary key,
  slug text not null unique,
  code text not null unique,
  title text not null,
  summary text not null,
  level text not null default 'Foundation',
  status text not null default 'draft',
  accent text not null default '#eeb02b',
  pass_percent integer not null default 80,
  estimated_minutes integer not null default 0,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table academy_learners add column if not exists subscription_plan text;
alter table academy_learners add column if not exists subscription_status text not null default 'none';
alter table academy_learners add column if not exists current_period_end timestamptz;
alter table academy_learners add column if not exists paystack_customer_code text;
alter table academy_learners add column if not exists paystack_subscription_code text;
alter table academy_learners add column if not exists paystack_plan_code text;

create table if not exists academy_modules (
  id serial primary key,
  course_id integer not null references academy_courses(id) on delete cascade,
  title text not null,
  description text,
  position integer not null default 0
);

create table if not exists academy_lessons (
  id serial primary key,
  module_id integer not null references academy_modules(id) on delete cascade,
  slug text not null,
  title text not null,
  kind text not null default 'reading',
  content text,
  video_url text,
  resource_url text,
  duration_minutes integer not null default 0,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists academy_lesson_progress (
  id serial primary key,
  learner_id integer not null references academy_learners(id) on delete cascade,
  lesson_id integer not null references academy_lessons(id) on delete cascade,
  completed boolean not null default false,
  last_position_seconds integer not null default 0,
  completed_at timestamptz,
  updated_at timestamptz not null default now()
);

create table if not exists academy_quiz_questions (
  id serial primary key,
  lesson_id integer not null references academy_lessons(id) on delete cascade,
  prompt text not null,
  explanation text,
  position integer not null default 0
);

create table if not exists academy_quiz_options (
  id serial primary key,
  question_id integer not null references academy_quiz_questions(id) on delete cascade,
  label text not null,
  correct boolean not null default false,
  position integer not null default 0
);

create table if not exists academy_quiz_attempts (
  id serial primary key,
  learner_id integer not null references academy_learners(id) on delete cascade,
  lesson_id integer not null references academy_lessons(id) on delete cascade,
  answers jsonb,
  score_percent integer not null,
  passed boolean not null default false,
  submitted_at timestamptz not null default now()
);

create table if not exists academy_enrollments (
  id serial primary key,
  learner_id integer not null references academy_learners(id) on delete cascade,
  course_id integer not null references academy_courses(id) on delete cascade,
  status text not null default 'active',
  enrolled_at timestamptz not null default now(),
  completed_at timestamptz
);

create table if not exists academy_certificates (
  id serial primary key,
  learner_id integer not null references academy_learners(id) on delete cascade,
  course_id integer not null references academy_courses(id) on delete cascade,
  certificate_number text not null unique,
  issued_at timestamptz not null default now(),
  revoked_at timestamptz
);

create unique index if not exists academy_modules_course_position_uidx on academy_modules(course_id, position);
create unique index if not exists academy_lessons_module_slug_uidx on academy_lessons(module_id, slug);
create unique index if not exists academy_progress_learner_lesson_uidx on academy_lesson_progress(learner_id, lesson_id);
create unique index if not exists academy_enrollments_learner_course_uidx on academy_enrollments(learner_id, course_id);
create unique index if not exists academy_certificates_learner_course_uidx on academy_certificates(learner_id, course_id);


do $jdl_course$
declare
  v_course_id integer;
  v_module_id integer;
  v_lesson_id integer;
  v_question_id integer;
  v_option_id integer;
  v_session jsonb;
  v_question jsonb;
  v_position integer;
  v_question_position integer;
begin
  insert into academy_courses
    (slug, code, title, summary, level, status, accent, pass_percent, estimated_minutes, published_at)
  values
    ('ogc-level-1', 'JDL-OGC01', 'Oil, Gas & Chemicals Inspection — Level 1',
     'Twelve JDL-authored client-review sessions covering safety, sampling, measurement, chemical inspection and quantity reporting.',
     'Foundation', 'published', '#eeb02b', 80, 380, now())
  on conflict (slug) do update set
    code = excluded.code, title = excluded.title, summary = excluded.summary,
    level = excluded.level, status = excluded.status, accent = excluded.accent,
    pass_percent = excluded.pass_percent, estimated_minutes = excluded.estimated_minutes,
    updated_at = now()
  returning id into v_course_id;

  for v_session in
    select value from jsonb_array_elements($jdl_payload$[{"position":0,"slug":"inspection-foundations","title":"Independent inspection foundations","minutes":25,"kind":"quiz","content":"Why independent inspection matters\n\nAn inspector is an independent witness to a commercial movement. Your job is to establish what happened, how the quantity and quality were determined, and which records support the result. Custody transfer is the point at which responsibility for a cargo changes hands. Because several parties may rely on the same figures, measurements must be repeatable and observations must be reported without favouring any party.\n\nBefore attending a job, read the nomination and identify the cargo, location, parties, requested tests, reporting deadlines, agreed measurement basis and limits of your authority. Confirm which industry standard and local procedure apply. If an instruction is unclear, resolve it before treating a measurement as final. A commercially plausible number is not evidence that the work was done correctly.\n\nIn the field, record the sequence of events, equipment used, tank or line identity, witnesses, times, raw readings, changes in operating conditions and any protest or exception. Keep raw observations separate from later calculations. If the terminal and vessel figures differ, investigate the inputs systematically; never adjust a reading simply to make the totals agree.\n\nJDL practice: describe the observation, cite its source, state the applicable method, and explain any uncertainty. A clear exception reported promptly is more useful than a tidy but unsupported result.\n\nScope, standards and professional conduct\n\nThe nomination is the first control document. Turn it into a job checklist: movement type, cargo grade, custody-transfer points, tanks and lines, samples and tests, parties to witness the work, agreed standards, reporting form and required times. A request to “check quantity” is incomplete until the measurement basis and included inventories are known. The inspector can verify observations and calculations; the inspector cannot rewrite a contract or certify an unperformed test.\n\nStandards make measurements comparable across locations. Different parties may use different equipment, but a result is defensible when the agreed method, instrument checks, raw observations and calculation chain are known. Record a deviation as a deviation; obtain authorisation for a revised method rather than silently combining two methods.\n\nA useful field log is chronological. Record arrival, induction, opening and closing gauges, transfer changes, samples, witness names and protests. Distinguish what you directly saw from what an operator told you. A report can quote an operator's statement, but it should identify the source. Confidential commercial information belongs in the authorised report, not casual conversation.\n\nPractice task: write a nomination checklist for a fictional cargo that loads from two shore tanks into three vessel tanks. Include starting and ending line-state checks. Name the records needed to compare shore and vessel totals.\n\nPractice case: two parties disagree\n\nAt a fictional terminal, the shore report says 1,240 m³ and the vessel report says 1,228 m³. The inspector should first compare measurement times, tank identities, water deductions, temperatures, trim/list entries, line state and rounding. Write an exception log with the evidence for each figure. The 12 m³ difference is a question to investigate, not an amount to distribute between parties without evidence.\n\nDecision exercise: a supervisor asks you to omit a late valve change because the final figures are close. Record the change, its time, the source of the information and whether it could affect the comparison. Professional independence applies even when the omission would be convenient.","questions":[{"position":0,"prompt":"What should an inspector do when a nomination leaves the measurement basis unclear?","correct":"Clarify it before finalising measurements","incorrect":"Select whichever basis produces the expected quantity"},{"position":1,"prompt":"Which record should be retained?","correct":"The original field reading and its time","incorrect":"Only the final rounded figure"},{"position":2,"prompt":"A difference between shore and vessel figures should first lead to:","correct":"A documented check of inputs and conditions","incorrect":"A silent adjustment to one figure"},{"position":3,"prompt":"What turns a nomination into a usable field plan?","correct":"A checklist of scope, methods, tanks, samples and times","incorrect":"A target final number"},{"position":4,"prompt":"How should an operator's statement appear in a report?","correct":"Attributed to that operator","incorrect":"As the inspector's direct observation"}]},{"position":1,"slug":"safety-and-sds","title":"Safety planning and Safety Data Sheets","minutes":30,"kind":"quiz","content":"Plan the work before exposure\n\nInspection work can involve moving machinery, elevated access, flammable vapour, toxic cargo, pressure, weather and simultaneous operations. Begin with the site induction, permit requirements, current risk assessment and emergency arrangements. Identify the safe access route, communication method, isolation requirements and stop-work trigger. If actual conditions differ from the plan, pause and reassess with the responsible site personnel.\n\nRead the Safety Data Sheet for the actual product before handling it. Check the product identity, hazards, first aid, fire response, spill controls, handling and storage, exposure controls, physical properties, incompatibilities and transport information. The sheet informs the risk assessment; it does not replace site controls or competent supervision. A missing or mismatched sheet is a reason to stop and request clarification.\n\nBenzene exposure, hydrogen sulfide and oxygen-deficient atmospheres require particular attention. Do not rely on smell to detect hazardous gas. Use approved monitoring and the site's response plan. Confined-space entry needs a separate authorised system of work, atmospheric testing, attendant and rescue arrangements. An inspector should never enter merely because a tank appears empty.\n\nStatic electricity can build during sampling and transfer. Follow the approved bonding, grounding, equipment and operating controls for the product and site. Do not improvise a faster technique when the control is inconvenient. JDL expects a documented stop-work decision whenever a critical safety control is absent.\n\nHazard controls in detail\n\nRead the SDS as a decision tool. Identification confirms the material and supplier; hazard and ingredient sections describe the exposure concern; first-aid, fire and release sections shape the emergency response; handling and exposure sections guide controls; properties and stability identify conditions and incompatible materials; transport information informs sample dispatch. Some sections may state “no data”, which is an uncertainty to resolve rather than proof of safety.\n\nFor a task risk assessment, list the operation, hazard, exposure route, people affected, existing controls, remaining risk and stop condition. Consider access at height, slippery surfaces, moving equipment, vapour at a hatch, pressure in a sample point, lightning and simultaneous transfer operations. Recheck when the tank, product, weather or operating state changes.\n\nBenzene is an exposure concern in some petroleum cargoes. Hydrogen sulfide can incapacitate quickly and smell is unreliable. Use the site's gas monitoring, exclusion and emergency arrangements; no lesson should encourage opening a hatch or entering a space to “confirm” a reading. Confined-space entry is a separate, controlled activity with permit, atmospheric testing, communication, attendant and rescue capability. An inspector outside that authorisation must stay out.\n\nStatic control matters when liquid movement, sampling or clothing can create charge. Use approved conductive equipment and site bonding or grounding arrangements. The safe sampling rate and waiting period depend on the cargo and installation; this review course does not invent universal numbers.\n\nPractice task: for a fictional aromatic cargo, identify which SDS entries would change sample container selection, PPE, monitoring and transport packaging.\n\nPractice case: product identity changes\n\nA fictional job sheet names diesel, but the tank label and operator say a solvent blend. Stop sampling. Obtain a confirmed cargo identity and matching SDS, review the exposure and compatibility hazards, then update the risk assessment and instructions. Do not infer that diesel gloves, respiratory protection or sample bottles suit the new cargo.\n\nSDS reading exercise: locate the sheet's identification and hazard sections, first-aid and fire measures, spill response, handling, exposure controls, stability and transport information. Explain which entry changes your safe work plan. A sheet is useful only when it belongs to the material in front of you.","questions":[{"position":0,"prompt":"What if the SDS names a different product from the cargo?","correct":"Stop and obtain the correct sheet","incorrect":"Use the sheet anyway"},{"position":1,"prompt":"Can smell reliably establish that hydrogen sulfide is absent?","correct":"No","incorrect":"Yes"},{"position":2,"prompt":"What is needed before confined-space entry?","correct":"A separate authorised entry and rescue plan","incorrect":"A verbal assurance that the tank is empty"},{"position":3,"prompt":"What does 'no data' in a relevant SDS section mean?","correct":"An uncertainty to resolve","incorrect":"The hazard is absent"},{"position":4,"prompt":"When should a task risk assessment be revisited?","correct":"When conditions or cargo change","incorrect":"Only after a report is issued"}]},{"position":2,"slug":"ppe-and-respiratory-protection","title":"PPE and respiratory protection","minutes":25,"kind":"quiz","content":"Choose protection from the hazard\n\nPPE is the last layer after elimination, isolation and safe operating controls. Match head, eye, face, hand, foot and body protection to the task, product and site rules. Inspect each item before use; damaged gloves, contaminated clothing or unsuitable footwear can introduce a new risk. A face shield may supplement eye protection, but it does not replace the protection specified by the assessment.\n\nRespiratory equipment is selected by a competent person from a known contaminant, concentration, oxygen status and task duration. A filtering respirator does not supply oxygen. Air-purifying cartridges have contaminant-specific limits and cannot be assumed suitable for unknown or immediately dangerous atmospheres. Supplied-air or self-contained equipment requires training, inspection and a managed response plan.\n\nA tight-fitting mask must be fit tested and checked for a seal each time it is worn. Facial hair or a poor fit can defeat the protection. Record the device, cartridge or cylinder condition, required checks and any limitations in the job assessment. If monitoring or equipment is unavailable, do not substitute a different mask by guesswork.\n\nJDL practice: confirm the protection before opening a tank, handling a sample or entering a controlled area. Where the hazard exceeds the inspector's training or authorisation, withdraw and escalate.\n\nPPE selection and inspection\n\nA hard hat protects against specified impact hazards only when its shell and suspension are sound. Eye protection must fit the splash or particle hazard; a face shield is supplementary where the assessment requires goggles. Glove material must be compatible with the cargo and duration of contact. Safety footwear needs suitable grip and toe protection; contaminated clothing should be handled under the site's decontamination plan. Inspect, clean, replace and store equipment according to its instructions.\n\nHalf-mask and full-face filtering respirators cover different areas, but both rely on breathable ambient air, a known contaminant and a suitable filter or cartridge. A full-face unit may also protect the eyes; it does not turn an unknown atmosphere into a safe one. Self-contained breathing apparatus supplies air from a cylinder but requires specialised training, inspection, duration management and a rescue plan. Selection and change-out are tasks for competent personnel.\n\nBefore a tight-fitting device is used, confirm the user's training and fit test, inspect seals and valves, check cartridge identity and expiry, and perform the required user seal check. Facial hair, damaged straps or an incorrect cartridge can invalidate protection. Do not use a failed check as a reason to “work quickly”.\n\nPractice task: compare three fictional situations—liquid splash while sealing bottles, known vapour at a controlled sample station, and an unknown atmosphere near a hatch. State which protection decision can be made from the available evidence and which requires withdrawal and further assessment.\n\nPractice case: a mask is available but the hazard is unknown\n\nAn inspector finds a half-mask and cartridges in the equipment box, but no current atmosphere test or confirmed vapour identity. The presence of equipment does not establish suitability. Keep the hatch closed, request monitoring and competent selection, and use the site's escalation route. Compare this with a known, assessed exposure where the selected cartridge, fit test, inspection and change schedule are documented.\n\nReview exercise: distinguish protective gloves against contact, eye and face protection against splash, and respiratory protection against inhalation. For each, identify the hazard it controls and the failure mode that would make it ineffective.","questions":[{"position":0,"prompt":"Does an air-purifying respirator provide oxygen?","correct":"No","incorrect":"Yes"},{"position":1,"prompt":"How should respirator selection be made?","correct":"From the assessed hazard and competent approval","incorrect":"By choosing the most comfortable mask"},{"position":2,"prompt":"What can defeat a tight-fitting mask?","correct":"A poor face seal","incorrect":"A clean storage case"},{"position":3,"prompt":"What does a full-face filtering respirator still require?","correct":"Breathable air and a known compatible contaminant","incorrect":"Only a clean visor"},{"position":4,"prompt":"What should follow a failed seal check?","correct":"Stop use and correct the fit or equipment","incorrect":"Work faster"}]},{"position":3,"slug":"representative-sampling","title":"Representative and commodity-specific sampling","minutes":35,"kind":"quiz","content":"Define the sample's purpose\n\nA sample is representative only of the material, place and time it actually covers. Before collecting it, confirm the requested test, tank or line, cargo grade, sampling point, method, number of increments and required containers. Clean and inspect equipment. Avoid introducing residues from an earlier product. Record the level, time, temperature where relevant, and operating condition.\n\nAn all-levels sample is collected across the liquid depth; a running sample follows a controlled path through the column. Upper, middle and lower spot samples target defined zones and may reveal layering. A composite combines specified increments in agreed proportions. Tap and pipeline samples depend on point condition and whether the line is flowing and homogeneous. Vapour-pressure samples need equipment and handling that limit loss of volatile components. These methods answer different questions and are not interchangeable.\n\nFor crude oil, fuel oil, gasoline and clear chemical products, consider viscosity, volatility, water separation, contamination risk and material compatibility. Where an upper, middle or lower position must be calculated, use the verified liquid height and the governing method, then write down the resulting target depths. Do not call a convenience sample representative simply because it looks normal.\n\nJDL practice: connect every sample identifier to the exact source and method. If conditions prevent the agreed method, document the limitation and seek a revised instruction before proceeding.\n\nSampling methods and their limitations\n\nEquipment choice begins with the sample's purpose. A depth sampler, open bottle, closed system or pipeline point may collect very different material. Check cleanliness, material compatibility, opening and closure, and the sampling point's relation to the cargo. An all-levels or running sample spans a liquid column but can underrepresent layers if the filling rate or path is wrong. Spot samples deliberately describe a defined location. A composite is meaningful only when component increments and proportions are recorded.\n\nFor upper, middle and lower positions, first establish the actual product depth above free water. Use the nominated method's defined positions, calculate target gauges, and keep the field readings. If the product depth or roof condition changes, recalculate rather than reusing yesterday's positions. A bottom or dead-bottom sample may answer a contamination question but is not a replacement for a representative product sample.\n\nTap samples require a sound point and attention to stagnant branch content. Pipeline samples require stable flow and an agreed method for start, middle or end of transfer. Vapour-pressure work is especially vulnerable to evaporation and handling changes; use the specified sealed method and avoid unnecessary transfers between containers.\n\nCommodity decisions differ. Crude oil can contain water, sediment and viscosity gradients; fuel oil may require temperature-aware handling; gasoline loses light components easily; clear chemicals expose small contamination that a darker product might conceal. Sample identity, container material and mixing instructions should follow the requested test.\n\nPractice task: propose a sampling plan for a fictional layered shore tank and a flowing line. State what each bottle represents and what cannot be concluded from it.\n\nPractice case: a tank may be layered\n\nA fictional tank has 9.0 m of product above a measurable water layer. A single surface sample cannot establish the quality of the whole liquid column. If the nomination requires upper, middle and lower spot samples, calculate the target positions from the verified product depth using the agreed method, then record each actual depth. Keep samples separate until an authorised composite method states how to combine them.\n\nPractice case: transfer starts through a pipeline. A sample taken from a stagnant tap before flow may reflect residue in the branch rather than the new cargo. Record the tap condition and line state and use the approved flushing and sampling plan. For a volatile product, use a method and container designed to limit component loss. State exactly what each sample represents.","questions":[{"position":0,"prompt":"Can a single spot sample always stand for an entire tank?","correct":"No","incorrect":"Yes"},{"position":1,"prompt":"What must be checked before using a pipeline sampling point?","correct":"Its condition and the line's operating state","incorrect":"Only the bottle label"},{"position":2,"prompt":"Why use a vapour-pressure sampling method?","correct":"To limit loss of volatile components","incorrect":"To speed up labelling"},{"position":3,"prompt":"What must be known before calculating upper/middle/lower positions?","correct":"The verified product depth and nominated method","incorrect":"Only the bottle volume"},{"position":4,"prompt":"Why is a stagnant tap sample questionable?","correct":"It may contain branch residue","incorrect":"It is always more representative"}]},{"position":4,"slug":"sample-custody","title":"Sample handling, labelling and custody","minutes":25,"kind":"quiz","content":"Protect the sample after collection\n\nThe quality of a sample depends on everything that happens between collection and analysis. Select a compatible, clean container with the required closure and headspace. Follow the applicable method for volatile, hazardous or temperature-sensitive materials. Close promptly and protect the sample from contamination, evaporation, sunlight, breakage and mixing with another grade.\n\nLabel the container at the point of collection with a unique identifier, product, source, sampling method, date, time, sampler and requested analysis. Seal it where required and record the seal number. A label should make sense without relying on somebody's memory. If a correction is needed, preserve the original entry and document who made the change and why.\n\nMaintain a custody log for every handover: sender, receiver, time, condition, seal and destination. Pack samples according to the product hazards and carrier rules; confirm the SDS and transport information before dispatch. Never place incompatible samples together merely because they are going to the same laboratory.\n\nJDL practice: reconcile the field notes, sample register, seals and laboratory receipt. Any broken seal, missing time or unexplained delay is an exception to report, not a detail to conceal.\n\nFrom bottle to defensible result\n\nHandling begins before the first sample is collected. Prepare an inventory of clean, compatible bottles, labels, seals, absorbent or protective packaging, and a custody register. Verify requested tests and preservation needs with the laboratory. Sample volume and headspace depend on the method; a single fill rule cannot serve every product.\n\nAt collection, reconcile bottle ID, tank or line, depth or point, method, product, time and sampler against the field log. Seal where required, then record the seal before the sample leaves the inspector. If one sample is split for parties, identify each split and whether the preparation could affect analysis. Never relabel a bottle from memory after leaving the site.\n\nTransportation is another controlled step. Use compatible packaging and current dangerous-goods requirements where applicable. Record box count, condition, dispatch time, carrier and receipt. A clean sample result does not repair a missing handover. The report should identify compromised samples and avoid unconditional quality claims from them.\n\nPractice task: build a custody chain for six fictional bottles, including one retained counter-sample. At laboratory receipt, one bottle is warm and a second seal is broken. Explain which tests may be affected and how each exception should be reported.\n\nPractice case: three bottles, one missing seal\n\nThree fictional gasoline bottles are labelled with tank, sample depth and collection time. At laboratory receipt, one seal number differs from the field register. Preserve both records and the bottle condition, notify the receiving party and qualify the affected result. Do not retrospectively edit the field register to make the numbers match.\n\nCustody exercise: write a handover record from inspector to courier to laboratory that contains names, times, seal condition and container count. Ask what evidence is missing if a bottle arrives correctly labelled but without an intermediate receipt.","questions":[{"position":0,"prompt":"When should the sample be labelled?","correct":"At collection","incorrect":"After arrival at the laboratory"},{"position":1,"prompt":"What belongs in the custody record?","correct":"Each handover and seal condition","incorrect":"Only the final recipient"},{"position":2,"prompt":"How should a broken seal be handled?","correct":"Record and report it","incorrect":"Replace it without comment"},{"position":3,"prompt":"What should identify a split sample?","correct":"Its source and each split's preparation and recipient","incorrect":"Only the original bottle colour"},{"position":4,"prompt":"Can a good laboratory result restore a missing handover?","correct":"No","incorrect":"Yes"}]},{"position":5,"slug":"shore-tank-gauging","title":"Shore-tank gauging","minutes":35,"kind":"quiz","content":"Establish the tank reference\n\nA tank gauge is meaningful only when the tank, reference datum and measurement point are known. Verify tank identity, calibration table, reference height, gauge point and instrument condition. Check that the liquid is settled as required and note transfer, roof and valve conditions. Confirm safe access and vapour controls before opening a gauge hatch.\n\nInnage measures the distance from the datum to the liquid surface; outage measures from the reference point down to that surface. Select the method specified for the tank and use the matching calibration table. Repeat readings as the governing procedure requires. Record the raw tape or electronic observation, units, reference height and any disagreement, rather than entering only a converted volume.\n\nMeasure free water separately using the approved detection method. Floating roofs can change the effective volume; identify the roof position and whether it lies in a critical zone before applying a table or correction. A change in reference height, sediment, roof movement or a mismatched table can produce a convincing but false quantity.\n\nJDL practice: trace tank identity to table revision, raw level, water level, temperature and the person who observed each reading. If references do not reconcile, pause the calculation and investigate.\n\nStatic shore-tank measurement\n\nKnow the terms before using a table: datum is the zero reference; reference gauge point is the fixed point from which outage is observed; reference height links that point to the datum. Innage is liquid height from the datum; outage is the unfilled distance down from the reference point. The instrument may be a manual tape or approved electronic gauge. Confirm its identity, condition, graduations, calibration status and compatibility with the measurement method.\n\nTake a gauge at the authorised point under site vapour and access controls. Verify tank identity and reference height, note whether the product is moving, and record repeated raw readings under the governing method. If manual and electronic gauges disagree, investigate reference points, instrument status and operating conditions before selecting a result. Convert the accepted gauge using that tank's current calibration table; keep the table version in the audit trail.\n\nFree water is measured separately because it is part of TOV but not product GOV. Confirm detection method and whether the water interface is distinct. Floating-roof position can affect the effective volume and may be particularly uncertain in a critical zone. Document roof status and apply the tank-specific table instructions rather than inventing a roof correction.\n\nPractice task: given a fictional reference height of 12.000 m and two outages of 3.250 m and 3.260 m, calculate both implied innages. The 0.010 m difference is not resolved by averaging automatically; state what checks or repeat readings the method requires before volume lookup.\n\nWorked shore-gauge exercise\n\nFictional Tank S-4 has a verified reference height of 12.000 m. An outage reading is 3.250 m. The implied innage is 12.000 − 3.250 = 8.750 m, provided both readings use the same datum and units. Check the result against a direct innage reading before looking up volume in the approved S-4 table. A table for S-5 cannot be substituted, even if the tanks have similar dimensions.\n\nA separate water cut is 0.080 m. Record it independently, then obtain the corresponding free-water volume from the correct table or method. If a floating roof is near its critical zone, document roof condition and apply only the tank-specific instruction. The level-to-volume conversion cannot be completed from the level alone because the calibrated table has not been supplied in this exercise.","questions":[{"position":0,"prompt":"Which document converts a shore-tank level to volume?","correct":"The approved table for that tank","incorrect":"Any similar tank's table"},{"position":1,"prompt":"What is outage?","correct":"Distance from the reference point to the liquid surface","incorrect":"Depth of liquid from the datum"},{"position":2,"prompt":"Should free water be assumed from the product gauge?","correct":"No, measure it by the approved method","incorrect":"Yes"},{"position":3,"prompt":"With a 12.000 m reference height and 3.250 m outage, what is implied innage?","correct":"8.750 m","incorrect":"15.250 m"},{"position":4,"prompt":"What should happen when two gauges disagree?","correct":"Investigate references, instruments and conditions","incorrect":"Choose the larger value"}]},{"position":6,"slug":"marine-tank-gauging","title":"Marine-vessel tank measurement","minutes":35,"kind":"quiz","content":"Read the vessel as it is\n\nIdentify each cargo tank, its approved table, reference point and observed condition. Confirm whether tanks are full, partly filled or apparently empty and whether transfer or ballast operations affect the readings. Record vessel trim and list at the time of measurement. Marine tables and correction instructions are vessel-specific; never carry a shore-tank assumption across to a ship.\n\nTake cargo and free-water gauges consistently with the approved method. Trim and list can move the liquid surface relative to the gauge point, so apply the appropriate corrections before converting to volume. Keep observed and corrected figures separate. For on-board quantity before loading and remaining on board after discharge, inspect and record each relevant tank and line condition; a nominally empty tank may still contain measurable material.\n\nDisputes often arise when tank status, water cuts, trim, list or unmeasured residues are treated differently by two parties. Reconcile the times and inputs before comparing totals. Document inaccessible tanks, equipment failures or conditions that prevent a reliable observation.\n\nJDL practice: build a tank-by-tank record with raw cargo gauge, water gauge, trim, list, correction source, temperature and calculated volume. The total is only as dependable as its least supported tank entry.\n\nShip measurements and reconciliation\n\nA vessel has multiple tanks, different reference points and tables, and a changing attitude in water. Confirm tank identity, opening and gauge point, whether the tank is full or partly full, and the current trim and list. Record cargo level and water level as raw observations. The vessel's approved table and correction instructions determine how these become volume; shore-tank rules cannot be assumed.\n\nTrim changes the fore-to-aft liquid surface relative to the gauge point; list changes the side-to-side surface. Apply the specified correction for the tank and gauge location, then preserve both observed and corrected levels. For water, a shallow layer may need a different correction or table treatment from the cargo. Record the correction source and any tank for which it is unavailable.\n\nOBQ is material on board before loading; ROB is material left after discharge. Inspect relevant tanks and, where instructed, connected lines. Describe whether residue is liquid, non-liquid or unmeasurable under the applicable method. An estimated zero should not be reported as a measured zero.\n\nPractice task: produce a tank-by-tank worksheet for a fictional vessel with three cargo tanks. Include observed cargo and water levels, trim, list, corrected levels, table volumes and exceptions. Reconcile a discrepancy by reviewing the individual tanks rather than adjusting the grand total.\n\nWorked marine-record exercise\n\nFictional Vessel V-2 reports Tank 3 cargo outage of 1.620 m, water outage of 8.940 m, trim of 0.6 m by stern and list of 0.4° to port. Record all four observations and the gauge time. Retrieve the V-2 Tank 3 correction instructions; do not invent a trim or list factor. The corrected cargo and water levels then enter the approved tank table separately.\n\nBefore loading, Tank 3 contains a measured residue; after discharge, another residue remains. Record these as separate OBQ and ROB observations with their own dates and conditions. A repeated total from the vessel's earlier report is not a new measurement.\n\nFictional table worksheet: for this classroom case only, the exercise supplies a combined cargo-outage correction of −0.010 m, so corrected outage is 1.610 m. The supplied fictional vessel table maps that corrected gauge to TOV 820.000 m³ and maps the separately corrected water observation to 3.000 m³ of free water. GOV = 820.000 − 3.000 = 817.000 m³. With supplied VCF 0.98500, GSV = 804.745 m³. With supplied S&W fraction 0.00200, NSV = 804.745 × 0.99800 = 803.13551 m³ before required rounding. With a compatible illustrative weight conversion factor of 0.84000 t/m³, apparent mass is 674.6338284 t before required rounding. These table outputs and factors are invented exercise data, not a real vessel calibration. In field work, obtain the actual V-2 tables, correction instructions and contract basis.","questions":[{"position":0,"prompt":"Why record trim and list?","correct":"They can affect the observed gauge and volume","incorrect":"They identify the vessel owner"},{"position":1,"prompt":"What does ROB describe?","correct":"Material remaining on board after discharge","incorrect":"The expected bill-of-lading quantity"},{"position":2,"prompt":"How should an inaccessible tank be treated?","correct":"Disclose the limitation","incorrect":"Enter zero without explanation"},{"position":3,"prompt":"Why keep observed and corrected levels separate?","correct":"To audit trim/list treatment","incorrect":"To make the report longer"},{"position":4,"prompt":"Is an estimated empty tank a measured zero?","correct":"No","incorrect":"Yes"}]},{"position":7,"slug":"temperature-determination","title":"Temperature determination","minutes":30,"kind":"quiz","content":"Temperature is a measured input\n\nPetroleum volume changes with temperature, so an unsupported temperature can spoil an otherwise careful gauge. Confirm the thermometer type, identification, range, calibration or verification status and suitability for the cargo. Liquid-in-glass and portable electronic devices have different handling and response characteristics. Follow the approved instrument instructions rather than assuming an instant reading is stable.\n\nDetermine how many readings and depths are needed for a representative tank temperature. Lower the instrument safely, allow the required immersion or stabilisation time, and record each actual reading with its depth, tank, time and units. Consider stratification, recent movement and whether the level is sufficient for the planned depths. Do not replace an unusual reading with an expected value; repeat or investigate it and retain both observations.\n\nUse the required averaging and rounding rule only after the raw values have been recorded. Keep cargo temperature distinct from shell temperature or an ambient estimate used for a separate correction. The same temperature record should be traceable through the later volume calculation.\n\nJDL practice: a defensible result states the instrument, verification, reading locations, stabilisation and method used to obtain the reported average.\n\nInstrument verification and representative reading\n\nLiquid-in-glass thermometers and portable electronic instruments require different checks, handling and stabilisation. Before use, confirm calibration or verification evidence, measurement range, resolution, protective condition and units. A damaged instrument or an expired check is not made valid by a plausible display.\n\nChoose depths and reading count from the governing method and actual tank depth. Temperature can vary after heating, circulation, blending or a long settling period. Allow immersion or electronic stabilisation as specified, then record each reading, location, time and instrument. If readings differ materially, investigate whether the tank is stratified and whether a simple average is appropriate.\n\nA reported temperature is an input to the correction chain, not a decorative line on a form. Check whether the calculation uses observed liquid temperature, tank-shell temperature or a separate ambient observation. Record the source of each; do not substitute one for another. Keep the original precision until the governing rounding step.\n\nPractice task: three fictional readings are 27.2°C, 27.8°C and 28.0°C. Compute the unweighted mean, then explain why an approved method might require different depth weighting. If the middle reading was taken during circulation, identify the extra evidence needed before final reporting.\n\nWorked temperature exercise\n\nFictional Tank S-4 has stable readings of 27.2°C, 27.8°C and 28.0°C at approved depths. If the agreed method calls for an unweighted arithmetic mean, the illustrative result is (27.2 + 27.8 + 28.0) ÷ 3 = 27.666…°C, rounded only by the specified rule. If the method requires depth weighting, this calculation is not valid. Record all three readings and locations before selecting the reporting basis.\n\nA fourth reading of 34.0°C taken during a recirculation event should not be quietly deleted. Keep its time and event, investigate whether it belongs to the same measurement condition, then state the basis used for the final temperature.","questions":[{"position":0,"prompt":"What should happen before an electronic temperature is recorded?","correct":"Allow it to stabilise as required","incorrect":"Copy the first displayed number"},{"position":1,"prompt":"Why take readings at more than one depth?","correct":"To assess a representative temperature","incorrect":"To avoid recording the tank ID"},{"position":2,"prompt":"How should an unusual raw reading be handled?","correct":"Keep it and investigate or repeat","incorrect":"Erase it"},{"position":3,"prompt":"What is the unweighted mean of 27.2, 27.8 and 28.0°C?","correct":"About 27.67°C before required rounding","incorrect":"28.00°C"},{"position":4,"prompt":"Why might this mean be inappropriate?","correct":"The method may require depth weighting or the tank may be stratified","incorrect":"The instrument has a serial number"}]},{"position":8,"slug":"pipeline-fullness","title":"Pipeline fullness and transfer conditions","minutes":30,"kind":"quiz","content":"Account for the line between measurement points\n\nA shore-to-vessel difference may reflect a change in the material held in pipelines rather than a measurement error. Identify the route, line capacity, valve state, product interface and whether the line was full at the beginning and end of transfer. Agree a verification method with the responsible parties before the movement where possible.\n\nApproved approaches may include documented circulation, displacement with a known material, controlled high-point checks, pigging or line-pressure evidence. Each has limits and safety requirements. A pressure indication alone does not prove that every part of a line contains the same liquid; high points, gas pockets and interfaces matter. Avoid opening or bleeding a line without site authorisation and controls.\n\nRecord who performed the check, when it occurred, the line configuration, measured or observed evidence and the agreed tolerance. If the beginning and ending states differ, show the estimated effect separately from tank measurements and state the uncertainty.\n\nJDL practice: do not force shore and vessel figures to match by assigning an unexplained difference to pipeline fullness. Establish evidence for the line condition first.\n\nLine condition and the cargo balance\n\nA pipeline can retain product, gas or an interface between grades. A change in line inventory between start and finish can appear as a shore-vessel quantity difference. Map the route, branches, high points, valves, capacity and product at each end. Ask whether the line is static, circulating, displaced or pressurised and what each observation actually proves.\n\nCirculation may help establish a uniform product path but needs a documented loop and operating conditions. Displacement introduces a known fluid or product, with an interface that must be tracked. A high-point check can identify gas at a local point but may not represent the whole route. Pigging provides a physical movement indication yet depends on pig travel and recovered material. Line pack or pressure evidence is indirect and must be interpreted with temperature and route geometry. The terminal selects and controls the safe method.\n\nAgree a tolerance and evidence basis before transfer, record beginning and ending states, and quantify the possible inventory change only when supported. Show a line adjustment separately from tank measurements. If the method cannot verify fullness, state that uncertainty instead of declaring the line full.\n\nPractice task: a fictional line holds 18 m³ full and a supported end-state estimate indicates 5 m³ void. Explain how this might affect comparison, and what measurements would be needed before applying an actual quantity adjustment.\n\nWorked line-state exercise\n\nA fictional line holds approximately 18 m³ when full. Evidence indicates it began full and ended with an estimated 5 m³ void. The potential change in line inventory is 5 m³, but this estimate is not a tank reading and should not automatically be inserted as a correction. Verify the line route, valve state and method used to infer the void, then report the supported line effect and uncertainty alongside the shore-vessel comparison.\n\nMethod-selection exercise: compare circulation, displacement, high-point observation, pigging and pressure evidence. For each, ask who operates the line, which parts of the route are actually verified, what hazards the check introduces and how its effectiveness will be documented.","questions":[{"position":0,"prompt":"Can a line-pressure reading by itself prove uniform fullness?","correct":"No","incorrect":"Yes"},{"position":1,"prompt":"When is it best to agree the line-verification method?","correct":"Before transfer","incorrect":"After the final report"},{"position":2,"prompt":"What if start and finish line states differ?","correct":"Document and quantify the effect where supported","incorrect":"Ignore the difference"},{"position":3,"prompt":"Who selects and controls a safe line-fullness method?","correct":"The responsible terminal personnel","incorrect":"An inspector acting alone"},{"position":4,"prompt":"How should a supported line-inventory effect be presented?","correct":"Separately from tank observations","incorrect":"Hidden inside a tank gauge"}]},{"position":9,"slug":"quantity-calculations","title":"Quantity calculation and audit trail","minutes":40,"kind":"quiz","content":"Calculate in a visible sequence\n\nStart with observed data: tank identity, raw gauge, water cut, temperature, trim or list and the relevant table. Convert the corrected level to total observed volume (TOV). Determine free-water volume separately, then gross observed volume (GOV) as the product volume at observed conditions. Apply only the corrections required for that tank, such as steel-shell or floating-roof effects, using approved references.\n\nApply the correct volume correction factor to obtain gross standard volume (GSV). If the contract requires a net standard volume (NSV), apply the specified sediment-and-water basis. Apparent mass or weight in air requires the appropriate density and conversion basis. Symbols, units, reference temperature and rounding must be consistent throughout. Do not mix an observed volume in one unit with a correction factor or density defined for another basis.\n\nWork one tank at a time and retain intermediate figures before adding totals. Show each source table or factor, the calculation order and the rounding rule. Recalculate a sample tank independently and compare the final shore and vessel numbers only after both chains have been checked.\n\nJDL practice: the report should let a reviewer reproduce the quantity from field notes. A spreadsheet output without raw inputs, table references and correction basis is not an audit trail.\n\nCalculation structure and worked checks\n\nUse a worksheet with two columns: observed data and calculated data. Observed data include raw gauges, free-water cuts, temperatures, trim/list, density or test result and operating times. Calculated data include corrected levels, table volumes, shell or roof effects where applicable, GOV, VCF, GSV, S&W adjustment, NSV and apparent mass. Label every factor with its source, basis and units.\n\nFor shore tanks, begin with the calibrated table's TOV and deduct the table-derived free-water volume to find product GOV. Apply any required steel-shell or floating-roof adjustment in the order specified by the approved method. For a ship, correct levels for trim and list as required, use the vessel tables tank by tank, and derive GOV after the separate water treatment. Then apply the correct volume correction factor to obtain GSV. The S&W adjustment gives NSV only on the contract's specified basis. A weight conversion factor or density converts volume to apparent mass only when units and reference conditions are compatible.\n\nUse decimal places and rounding as the agreed method requires. Premature rounding can change totals. Recompute one tank independently and check dimensional consistency: metres cannot be subtracted from cubic metres; a factor for litres cannot silently be used with barrels. Report the calculation sequence so a reviewer can rebuild it from raw notes.\n\nConversion practice: 1 m³ equals 1,000 L. A fictional GOV of 1,240.00 m³ is 1,240,000 L. Converting units does not change the physical quantity; changing reference temperature or density basis can. Define innage, outage, TOV, GOV, GSV, NSV, VCF, free water, trim, list, OBQ and ROB in your own words before completing the final assessment.\n\nWorked calculation exercise: shore tank\n\nThe following fictional values are supplied after approved tank-table lookup and corrections; they are not field instructions. TOV = 1,248.60 m³ and free-water volume = 8.60 m³. GOV = 1,240.00 m³. If the exercise supplies VCF = 0.98400 on the correct product and reference-temperature basis, GSV = 1,240.00 × 0.98400 = 1,220.16 m³. If the agreed S&W fraction is 0.00500, NSV = 1,220.16 × (1 − 0.00500) = 1,214.0592 m³ before specified rounding. With an illustrative weight conversion factor of 0.83500 t/m³ on a compatible basis, apparent mass = 1,013.739432 t before specified rounding. Write the units at every step.\n\nMarine variation: start from each vessel tank's observed levels and approved trim/list-corrected table volumes. Determine cargo and water volumes tank by tank, then apply the correct volume and mass basis. Never subtract a water level in metres from a cargo volume in cubic metres.\n\nGlossary check: TOV includes liquid and free water at observed conditions; GOV is observed product volume after free-water deduction; GSV is product volume on the specified standard-temperature basis; NSV applies the agreed sediment-and-water adjustment. A conversion table is usable only when its source units, target units, reference conditions and precision match the contract.","questions":[{"position":0,"prompt":"What is deducted from TOV to obtain product volume at observed conditions?","correct":"Free-water volume","incorrect":"The vessel's trim"},{"position":1,"prompt":"What converts observed product volume toward standard volume?","correct":"The applicable correction factor","incorrect":"The sample seal number"},{"position":2,"prompt":"When should rounding occur?","correct":"At the steps required by the agreed method","incorrect":"Whenever a number looks untidy"},{"position":3,"prompt":"If TOV is 1,248.60 m³ and free water is 8.60 m³, what is GOV?","correct":"1,240.00 m³","incorrect":"1,257.20 m³"},{"position":4,"prompt":"What is 1,240.00 m³ in litres?","correct":"1,240,000 L","incorrect":"1,240 L"}]},{"position":10,"slug":"chemical-and-wall-wash","title":"Chemical cargo inspection and wall-wash testing","minutes":35,"kind":"quiz","content":"Protect cargo quality and personal safety\n\nChemical inspection can demand tighter control of contamination, compatibility and previous-cargo residues than a routine petroleum movement. Confirm the cargo identity, specification, cleaning standard, coating compatibility, required tests and approved sampling materials. A sample container or hose suitable for one product can be unsuitable for another. Review the SDS and site controls for exposure, reaction and transport hazards.\n\nTank inspection and wall-wash testing are separate decisions. A visual inspection may identify residue, damage or moisture, but it does not establish every chemical cleanliness criterion. A wall wash uses an agreed solvent and test method to evaluate the accessible surface for specified contaminants. Confirm the test location, solvent purity, sample container, blank, handling and laboratory method. Follow the approved procedure and avoid treating a local passing result as proof of every unseen surface.\n\nCompare findings with the nomination's acceptance criteria. Record tanks tested, areas reached, exceptions, witnesses and any limitation caused by access or safety. Cargo-line condition and sample transport may also affect quality. Where results are ambiguous, request competent review before declaring a tank fit.\n\nJDL practice: report what was inspected and tested, the method and its limits, and the exact criterion used for acceptance. Never issue a blanket cleanliness statement from incomplete evidence.\n\nChemical inspection and wall-wash decisions\n\nProduct and chemical inspections share measurement and custody principles, but chemical cargoes can have stricter contamination and compatibility limits. Confirm the exact specification, previous cargo, tank coating, cleaning evidence, line condition and authorised test plan. Quality field tests and tank observation are distinct forms of evidence. A test result outside specification needs clear identity and sample custody before the inspector draws a conclusion.\n\nWall wash is a defined test of selected tank surfaces using an agreed solvent and collection method. Select accessible areas under a safe entry or external test plan, use clean compatible equipment, identify solvent batch and blanks, collect and label each wash, and preserve the method's required handling. Funnel collection and filter-paper or blotter observations may serve different test aims; neither is a universal cleanliness certificate.\n\nRecord the tank areas inspected, areas not reached, previous-cargo concerns, laboratory method and acceptance criteria. Consider cargo pipelines and hoses separately because a clean tank can still receive contaminated cargo through a dirty line. A water-white chemical may reveal trace colour or haze, but appearance alone is not every specified laboratory test.\n\nPractice task: a fictional vessel's Tank C-7 passes a visual check but fails one nominated wall-wash result. Trace the sample, blank, solvent, test location and method; report the failure or uncertainty before claiming the tank is fit.\n\nPractice case: a chemical tank looks clean\n\nFictional Tank C-7 is visually clear, but the nominated cargo has a strict water and residue specification. A visual pass alone cannot establish fitness. Review the prior cargo, tank coating, cleaning record, sample compatibility, specified wall-wash tests and required acceptance basis. Map reachable test points and disclose areas that cannot be inspected.\n\nWall-wash comparison: an agreed funnel collection may recover wash solvent from a selected area, while a filter-paper or blotter approach may show local residue. These observations answer different questions. A blank helps distinguish contamination from the solvent, equipment or container. Use the nominated laboratory method for interpretation. A passing local test does not prove that cargo lines, hidden surfaces or every tank area are clean.","questions":[{"position":0,"prompt":"Does a clear visual inspection replace every wall-wash test?","correct":"No","incorrect":"Yes"},{"position":1,"prompt":"What should be confirmed before selecting a wall-wash solvent?","correct":"The agreed method and solvent compatibility","incorrect":"Only the bottle size"},{"position":2,"prompt":"How should uninspected tank areas be reported?","correct":"As a limitation","incorrect":"As clean by assumption"},{"position":3,"prompt":"What does a wall-wash blank help identify?","correct":"Contamination from solvent, equipment or container","incorrect":"The vessel's trim"},{"position":4,"prompt":"Does a clean tank surface establish a clean cargo line?","correct":"No","incorrect":"Yes"}]},{"position":11,"slug":"level-one-assessment","title":"Integrated Level 1 assessment","minutes":35,"kind":"assessment","content":"Put the complete workflow together\n\nA reliable inspection begins with a clear nomination and safe work plan. Verify cargo identity and SDS, site controls, authorisation, equipment and measurement standards. Establish tank and line conditions before transfer. Take raw gauges, water and temperature readings; select samples for the requested tests; label, seal and track every handover.\n\nCalculate tank quantities from traceable observations, approved tables and correction factors. Review trim, list, roof and line-state effects where applicable. Compare shore and vessel figures without hiding differences. Investigate anomalies using times, readings, equipment checks, calibration references, operating events and sample records. Report the result, exceptions and uncertainty promptly.\n\nScenario: a shore tank has a changed reference height, the vessel is trimmed, and the pipeline was partly drained after transfer. A valid report does not simply choose one party's figure. It verifies the tank reference, applies the approved vessel correction, documents the line change and explains which comparison remains uncertain.\n\nScenario: a chemical sample arrives with a broken seal and an apparently acceptable laboratory result. The result may still be informative, but its chain of custody is compromised. Record the exception and seek direction on resampling or qualification before making a definitive quality claim.\n\nJDL practice: competence means knowing when to measure, when to stop, when to seek specialist review and how to leave an honest record that another inspector can audit.\n\nCapstone instructions\n\nUse the fictional V-2/S-4 movement to prepare a complete inspection pack. First, make a nomination checklist and safety decision. Second, specify observations needed for shore tanks, vessel tanks, line condition, temperature and samples. Third, prepare sample labels and a custody log. Fourth, build shore and vessel quantity chains with supplied exercise tables. Fifth, prepare an exception report covering a changed reference height, altered line fill and disputed seal.\n\nFor every conclusion, show the source observation, method and limitation. A calculation may be arithmetically correct while its input is unverified. A quality result may be analytically plausible while custody is compromised. A safe inspector can stop and ask for a revised method.\n\nPeer-review task: exchange reports with another learner. Attempt to reproduce each tank total and locate every sample from its identifier. List missing evidence, ambiguous units and unsupported assertions. Revise the report without deleting the original observations.\n\nIntegrated fictional exercise\n\nVessel V-2 loads from shore Tank S-4 through a line whose ending fill state differs from its start. The product is volatile; one tank has stratified temperature and one sample seal is disputed. Build a report plan: confirm safe controls and SDS; identify approved sample method; retain raw shore and vessel gauges and water cuts; verify tank tables, temperatures and corrections; document line evidence; preserve custody exceptions; calculate each quantity chain; state the remaining uncertainty.\n\nThe correct response is not a single number. It is a transparent, reproducible account of what was measured, what was calculated, which result remains qualified and what further evidence is needed.","questions":[{"position":0,"prompt":"What should happen if a reference height has changed?","correct":"Verify the reference before calculating","incorrect":"Use the earlier height silently"},{"position":1,"prompt":"What does a broken sample seal affect?","correct":"Confidence in custody and result interpretation","incorrect":"Only the appearance of the bottle"},{"position":2,"prompt":"How should a shore-vessel difference be reported?","correct":"With investigated inputs and remaining uncertainty","incorrect":"As zero after adjustment"},{"position":3,"prompt":"What should a peer reviewer be able to reproduce?","correct":"Each tank quantity from raw evidence","incorrect":"Only the report title"},{"position":4,"prompt":"How should a qualified quality result be presented?","correct":"With its custody exception and limitation","incorrect":"As an unconditional pass"}]}]$jdl_payload$::jsonb)
  loop
    v_position := (v_session->>'position')::integer;
    insert into academy_modules (course_id, title, description, position)
    values (v_course_id, 'Session ' || (v_position + 1), v_session->>'title', v_position)
    on conflict (course_id, position) do update set
      title = excluded.title, description = excluded.description
    returning id into v_module_id;

    insert into academy_lessons
      (module_id, slug, title, kind, content, duration_minutes, position, published)
    values
      (v_module_id, v_session->>'slug', v_session->>'title', v_session->>'kind',
       v_session->>'content', (v_session->>'minutes')::integer, 0, true)
    on conflict (module_id, slug) do update set
      title = excluded.title, kind = excluded.kind, content = excluded.content,
      duration_minutes = excluded.duration_minutes, position = 0, published = true
    returning id into v_lesson_id;

    for v_question in
      select value from jsonb_array_elements(v_session->'questions')
    loop
      v_question_position := (v_question->>'position')::integer;
      select id into v_question_id from academy_quiz_questions
      where lesson_id = v_lesson_id and position = v_question_position
      order by id limit 1;
      if v_question_id is null then
        insert into academy_quiz_questions (lesson_id, prompt, explanation, position)
        values (v_lesson_id, v_question->>'prompt', v_question->>'correct', v_question_position)
        returning id into v_question_id;
      else
        update academy_quiz_questions set
          prompt = v_question->>'prompt', explanation = v_question->>'correct'
        where id = v_question_id;
      end if;

      select id into v_option_id from academy_quiz_options
      where question_id = v_question_id and position = 0 order by id limit 1;
      if v_option_id is null then
        insert into academy_quiz_options (question_id, label, correct, position)
        values (v_question_id, v_question->>'correct', true, 0);
      else
        update academy_quiz_options set label = v_question->>'correct', correct = true
        where id = v_option_id;
      end if;

      select id into v_option_id from academy_quiz_options
      where question_id = v_question_id and position = 1 order by id limit 1;
      if v_option_id is null then
        insert into academy_quiz_options (question_id, label, correct, position)
        values (v_question_id, v_question->>'incorrect', false, 1);
      else
        update academy_quiz_options set label = v_question->>'incorrect', correct = false
        where id = v_option_id;
      end if;
      v_question_id := null;
      v_option_id := null;
    end loop;
  end loop;
end;
$jdl_course$;

commit;

-- Verification: expect 12 sessions and 60 questions for this course.
select count(distinct m.id) as sessions, count(distinct l.id) as lessons,
       count(distinct q.id) as questions
from academy_courses c
join academy_modules m on m.course_id = c.id
join academy_lessons l on l.module_id = m.id
left join academy_quiz_questions q on q.lesson_id = l.id
where c.slug = 'ogc-level-1';
